class Solution {
public:
    vector<vector<string>> solveNQueens(int n) {
        vector<vector<string>> res;
        vector<string> board(n, string(n, '.'));
        vector<bool> cols(n, false), diag1(2 * n, false), diag2(2 * n, false);
        auto dfs = [&](auto& self, int r) -> void {
            if (r == n) {
                res.push_back(board);
                return;
            }
            for (int c = 0; c < n; ++c) {
                if (cols[c] || diag1[r - c + n] || diag2[r + c]) continue;
                cols[c] = diag1[r - c + n] = diag2[r + c] = true;
                board[r][c] = 'Q';
                self(self, r + 1);
                board[r][c] = '.';
                cols[c] = diag1[r - c + n] = diag2[r + c] = false;
            }
        };
        dfs(dfs, 0);
        return res;
    }
};

class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> res = new ArrayList<>();
        char[][] board = new char[n][n];
        for (char[] row : board) Arrays.fill(row, '.');
        boolean[] cols = new boolean[n];
        boolean[] diag1 = new boolean[2 * n];
        boolean[] diag2 = new boolean[2 * n];
        dfs(0, n, board, cols, diag1, diag2, res);
        return res;
    }
    private void dfs(int r, int n, char[][] board, boolean[] cols, boolean[] diag1, boolean[] diag2, List<List<String>> res) {
        if (r == n) {
            List<String> list = new ArrayList<>();
            for (char[] row : board) list.add(new String(row));
            res.add(list);
            return;
        }
        for (int c = 0; c < n; c++) {
            if (cols[c] || diag1[r - c + n] || diag2[r + c]) continue;
            cols[c] = diag1[r - c + n] = diag2[r + c] = true;
            board[r][c] = 'Q';
            dfs(r + 1, n, board, cols, diag1, diag2, res);
            board[r][c] = '.';
            cols[c] = diag1[r - c + n] = diag2[r + c] = false;
        }
    }
}

var solveNQueens = function(n) {
    const res = [];
    const board = Array.from({ length: n }, () => new Array(n).fill('.'));
    const cols = new Set();
    const diag1 = new Set();
    const diag2 = new Set();
    function backtrack(r) {
        if (r === n) {
            res.push(board.map(row => row.join('')));
            return;
        }
        for (let c = 0; c < n; c++) {
            if (cols.has(c) || diag1.has(r - c) || diag2.has(r + c)) continue;
            cols.add(c);
            diag1.add(r - c);
            diag2.add(r + c);
            board[r][c] = 'Q';
            backtrack(r + 1);
            board[r][c] = '.';
            cols.delete(c);
            diag1.delete(r - c);
            diag2.delete(r + c);
        }
    }
    backtrack(0);
    return res;
};
